mapper.update:
UPDATE RESERVATION
SET status = #{status}
WHERE reservation_id = #{reservationId}

mapper.select:
SELECT 
FROM RESERVATION r
LEFT JOIN PLACE p ON r.place_id = p.place_id
WHERE r.member_id = #{memberId}
  AND r.place_id = #{placeId}
  AND r.visit_date = #{visitDate}
  AND r.status IN ('PENDING', 'PAID', 'CONFIRMED')
ORDER BY r.reservation_id DESC
LIMIT 1

mapper.update:
UPDATE RESERVATION
SET order_id = #{orderId},
    payment_type = #{paymentType},
    pg_tid = #{pgTid}
WHERE reservation_id = #{reservationId}

mapper.select:
SELECT COUNT(*)
FROM RESERVATION
WHERE place_id = #{placeId}
  AND status IN ('PENDING', 'PAID', 'CONFIRMED')
  AND visit_date < #{checkOutDate}
  AND #{checkInDate} < COALESCE(check_out_date, DATE_ADD(visit_date, INTERVAL 1 DAY))

SELECT COUNT(*)
FROM PLACE_CLOSED_DATE
WHERE place_id = #{placeId}
  AND closed_date >= #{fromDate}
  AND closed_date < #{toDate}

SELECT COALESCE(SUM(headcount), 0)
FROM RESERVATION
WHERE place_id = #{placeId}
  AND visit_date = #{visitDate}
  AND status IN ('PENDING', 'PAID', 'CONFIRMED')
